if(panel==='text'){content.append(make('button',{class:'primary',onclick:()=>mutate(()=>project.texts.push({id:uid(),text:'Your text',at:head,end:Math.min(head+3,Math.max(total(),head+3)),size:.08,x:.5,y:.8,colour:'#ffffff'}))},'＋ Add text at playhead'));for(const t of project.texts){const text=make('textarea',{'aria-label':'Overlay text'},t.text);text.addEventListener('change',()=>mutate(()=>t.text=text.value));content.append(make('div',{class:'text-item'},text,field('Size',t.size,.02,.25,.01,v=>t.size=v),field('Position X',t.x,0,1,.01,v=>t.x=v),field('Position Y',t.y,0,1,.01,v=>t.y=v),make('label',{},'Colour',textInput(t.colour,'Text colour',v=>mutate(()=>t.colour=v),'color')),make('label',{},'Starts (s)',textInput(t.at,'Text start',v=>mutate(()=>t.at=clamp(v,0,total())),'number')),make('label',{},'Ends (s)',textInput(t.end,'Text end',v=>mutate(()=>t.end=clamp(v,t.at,86400)),'number')),make('button',{onclick:()=>mutate(()=>project.texts=project.texts.filter(x=>x.id!==t.id))},'Remove text')));}return;}
