async function thumbnail(job){if(!thumbA||job.gen!==generation||!job.canvas.isConnected)return;try{const {item,panel:kind,t}=job;const frames=[{rgba:thumbA.slice(),grade:kind==='looks'?item.grade:{},effect:kind==='effects'?item.id:null,progress:t,frame:Math.floor(t*48)}];if(kind==='transitions')frames.push({rgba:thumbB.slice()});const rgba=await request('render',{w:120,h:68,frames,transition:item.id,t});if(job.gen===generation)job.canvas.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(rgba),120,68),0,0);}catch(e){console.error('Thumbnail',e);}}
