function updateTimeline(){const clips=$('#clips');clips.replaceChildren();for(const s of layout(project.clips)){const c=s.clip,m=source(c.media);const label=make('span',{class:'clip-name'},m?.name||'Missing media');const badge=c.transition?catalogue?.transitions.find(t=>t.id===c.transition.id)?.name:'';clips.append(make('button',{class:c.id===selected?'selected':'',style:`width:${Math.max(105,Math.min(350,duration(c)*55))}px`,'data-id':c.id,role:'listitem',onclick:()=>{pause();selected=c.id;head=s.start;changed();}},label,make('span',{},`${clock(duration(c))} · ${c.speed}×`),make('span',{class:'transition-badge'},badge||'Straight cut')));}const settings=$('#clip-settings');settings.replaceChildren();const c=current();if(c){const m=source(c.media);for(const [label,key,min,max,step] of [['In','in',0,Math.max(0,c.out-1/FPS),.1],['Out','out',c.in+1/FPS,m?.type==='image'?3600:m?.duration||c.out,.1],['Speed','speed',.25,4,.25]]){const input=make('input',{type:'number',value:c[key].toFixed(2),min,max,step,'aria-label':label});input.addEventListener('change',()=>mutate(()=>{c[key]=clamp(input.value,min,max);},false));settings.append(make('label',{},label,input));}settings.append(make('label',{},'Volume',make('input',{type:'range',min:0,max:1,step:.05,value:c.volume,'aria-label':'Clip volume',onchange:e=>mutate(()=>c.volume=+e.target.value,false)})),make('label',{},'Zoom',make('input',{type:'number',min:1,max:3,step:.1,value:c.zoom,'aria-label':'Clip zoom',onchange:e=>mutate(()=>c.zoom=clamp(e.target.value,1,3),false)})));}$('#project-name').value=project.name;$('#aspect').value=project.aspect;$('#fill-frame').checked=project.fill;$('#undo').disabled=!history.length||exporting;$('#redo').disabled=!future.length||exporting;$('#project-summary').textContent=`${project.clips.length} clips · ${project.audio.length} audio tracks · ${project.texts.length} text overlays`;markTransport();}
function doSplit(){if(!activeClipRequired())return;const next=split(project.clips,selected,head);if(!next)return notice('Move the playhead inside the selected clip, beyond its incoming transition.');mutate(()=>project.clips=next);}
function doDelete(){if(!current())return;mutate(()=>{project.clips=project.clips.filter(c=>c.id!==selected);selected=project.clips[0]?.id||null;if(project.clips[0])project.clips[0].transition=null;});}
