const dbPromise=new Promise((resolve,reject)=>{const open=indexedDB.open('lookroom-editor',1);open.onupgradeneeded=()=>open.result.createObjectStore('projects');open.onsuccess=()=>resolve(open.result);open.onerror=()=>reject(open.error);});
dbPromise.catch(()=>{});
