async function restore(data){const loaded=[];try{for(const m of data.media){const file=m.file instanceof Blob?new File([m.file],m.name,{type:m.file.type}):await fetch(m.data).then(r=>r.blob()).then(b=>new File([b],m.name,{type:b.type}));loaded.push(await importFile(file,m.id));}const p=validateProject(data.project,loaded);pause();cleanMedia();media=loaded;project=p;history=[];future=[];head=0;selected=project.clips[0]?.id||null;changed();}catch(e){for(const m of loaded)URL.revokeObjectURL(m.url);throw e;}}
