const toDataURL=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob);});
const filename=()=>project.name.replace(/[^\p{L}\p{N}\- _]/gu,'').trim()||'Lookroom';
async function saveProject(){const bytes=media.reduce((n,m)=>n+m.file.size,0);if(bytes>250*1024*1024)throw new Error('This portable project is larger than 250 MB. The edit is still saved on this device; use smaller source clips for a portable project.');$('#save-state').textContent='Preparing project…';const packed=[];for(const m of media)packed.push({id:m.id,name:m.name,data:await toDataURL(m.file)});await download(new Blob([JSON.stringify({format:'lookroom-web',project,media:packed})],{type:'application/json'}),`${filename()}.lookroom.json`);$('#save-state').textContent='Project downloaded';}
function videoMime(){if(!window.MediaRecorder||!picture.captureStream)return null;return ['video/mp4;codecs=avc1.42E01E,mp4a.40.2','video/mp4','video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(x=>MediaRecorder.isTypeSupported(x));}
async function png(){pause();while(rendering)await new Promise(r=>setTimeout(r,20));await draw(head,+$('#export-size').value);const blob=await new Promise(r=>picture.toBlob(r,'image/png'));if(!blob)throw new Error('Could not create a PNG.');await download(blob,`${filename()}.png`);notice('Frame exported.');render();}
async function exportVideo(){if(exporting)return;const mime=videoMime();if(!mime)throw new Error('Video recording is not available in this browser. Use a recent Safari, Chrome or Edge, or export a PNG.');if(!total())throw new Error('Add a clip first.');pause();while(rendering)await new Promise(r=>setTimeout(r,20));await audioReady();for(const m of media)connectAudio(m);exporting=true;exportCancelled=false;const previousHead=head;head=0;const side=+$('#export-size').value;$('#export-progress').hidden=false;$('#export-cancel').hidden=false;$('#export-video').disabled=true;$('#export-image').disabled=true;document.body.classList.add('exporting');let stream;try{await prepare(0,true);await draw(0,side);stream=picture.captureStream(FPS);if(media.some(m=>m.type!=='image'))for(const track of audioDestination.stream.getAudioTracks())stream.addTrack(track.clone());const chunks=[];recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:side>=1080?8000000:4000000});const stopped=new Promise((resolve,reject)=>{recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=resolve;recorder.onerror=e=>reject(new Error(e.error?.message||'Video recording failed'));});recorder.start(500);playing=true;const began=performance.now(),length=total();while(!exportCancelled){head=Math.min(length,(performance.now()-began)/1000);await draw(head,side);$('#export-progress').value=head/length;markTransport();if(head>=length)break;await new Promise(requestAnimationFrame);}pauseMedia();playing=false;recorder.stop();await stopped;if(!exportCancelled){await download(new Blob(chunks,{type:mime}),`${filename()}.${mime.includes('mp4')?'mp4':'webm'}`);notice('Video exported.');}else notice('Export cancelled.');}finally{if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());recorder=null;playing=false;exporting=false;pauseMedia();head=previousHead;$('#export-video').disabled=false;$('#export-image').disabled=false;$('#export-cancel').hidden=true;$('#export-progress').hidden=true;document.body.classList.remove('exporting');changed(false);}}
function openExport(){$('#export-support').textContent=videoMime()?`Video format: ${videoMime().includes('mp4')?'MP4':'WebM'}. PNG is available for still images.`:'This browser supports PNG export. Video export needs MediaRecorder and canvas capture.';$('#export-video').disabled=!videoMime();$('#export-dialog').showModal();}
document.querySelectorAll('nav [data-panel]').forEach(b=>b.addEventListener('click',()=>{panel=b.dataset.panel;search='';category='All';renderPanel();}));
$('#media-input').onchange=run(async e=>{await addFiles([...e.target.files]);e.target.value='';});$('#new-project').onclick=()=>{if(exporting||!confirm('Start a new project? Save a portable project first if you want to keep this edit.'))return;mutate(()=>{project=emptyProject();selected=null;head=0;});};
$('#project-name').onchange=e=>mutate(()=>project.name=e.target.value||'Untitled Project',false);$('#aspect').onchange=e=>mutate(()=>project.aspect=e.target.value,false);$('#fill-frame').onchange=e=>mutate(()=>project.fill=e.target.checked,false);$('#quality').onchange=()=>render();
$('#play').onclick=run(()=>playing?pause():play());$('#seek').oninput=()=>{if(exporting)return;pause();head=+$('#seek').value;render();markTransport();};$('#back').onclick=()=>{if(exporting)return;pause();head=Math.max(0,head-1/FPS);render();};$('#forward').onclick=()=>{if(exporting)return;pause();head=Math.min(total(),head+1/FPS);render();};
$('#split').onclick=doSplit;$('#delete').onclick=doDelete;$('#duplicate').onclick=()=>{if(!activeClipRequired())return;mutate(()=>{const c=structuredClone(current());c.id=uid();c.transition=null;const i=project.clips.findIndex(x=>x.id===selected);project.clips.splice(i+1,0,c);selected=c.id;});};$('#move-left').onclick=()=>move(-1);$('#move-right').onclick=()=>move(1);$('#undo').onclick=()=>undo();$('#redo').onclick=()=>undo(true);
$('#save-project').onclick=run(saveProject);$('#open-project').onclick=()=>{if(!exporting)$('#project-input').click();};$('#project-input').onchange=run(async e=>{const file=e.target.files[0];if(!file)return;e.target.value='';if(file.size>350*1024*1024)throw new Error('The project file is too large.');const data=JSON.parse(await file.text());if(data.format!=='lookroom-web'||!Array.isArray(data.media)||data.media.length>500||data.media.some(m=>typeof m.data!=='string'||!m.data.startsWith('data:')))throw new Error('Choose a Lookroom web project with embedded media.');if(project.clips.length&&!confirm('Replace this edit with the saved project?'))return;await restore(data);notice('Project opened.');});
$('#snapshot').onclick=run(png);$('#export-open').onclick=openExport;$('#export-image').onclick=run(png);$('#export-video').onclick=run(exportVideo);$('#export-cancel').onclick=()=>{exportCancelled=true;};$('#export-dialog').addEventListener('cancel',e=>{if(exporting){e.preventDefault();exportCancelled=true;}});
document.addEventListener('keydown',run(e=>{if(exporting||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();return playing?pause():play();}if(e.key.toLowerCase()==='s'&&!e.ctrlKey&&!e.metaKey)doSplit();if(e.key==='Delete')doDelete();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();return saveProject();}}));
let dragDepth=0;document.addEventListener('dragenter',e=>{if(e.dataTransfer?.types.includes('Files')){e.preventDefault();dragDepth++;document.body.classList.add('dragging');}});document.addEventListener('dragleave',()=>{if(--dragDepth<=0)document.body.classList.remove('dragging');});document.addEventListener('dragover',e=>e.preventDefault());document.addEventListener('drop',run(async e=>{e.preventDefault();dragDepth=0;document.body.classList.remove('dragging');await addFiles([...e.dataTransfer.files]);}));
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(exporting){exportCancelled=true;notice('Export stopped because the editor moved to the background. Keep it visible while exporting.');}else pause();}});
window.addEventListener('beforeunload',e=>{if(exporting){e.preventDefault();e.returnValue='';}});
async function boot(){try{catalogue=await request('catalogue');thumbA=await request('sample',{w:120,h:68});thumbB=thumbA.slice();for(let i=0;i<thumbB.length;i+=4){thumbB[i]=Math.min(255,thumbB[i]*.6+65);thumbB[i+1]*=.65;thumbB[i+2]=Math.min(255,thumbB[i+2]*.8+30);}let saved;try{const db=await dbPromise;saved=await new Promise((resolve,reject)=>{const r=db.transaction('projects').objectStore('projects').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}catch{}if(saved)await restore(saved);else{const rgba=await request('sample',{w:960,h:540});const demo=document.createElement('canvas');demo.width=960;demo.height=540;demo.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(rgba),960,540),0,0);const blob=await new Promise(r=>demo.toBlob(r,'image/png'));const m=await importFile(new File([blob],'Sample landscape.png',{type:'image/png'}));media.push(m);const a=newClip(m),b=newClip(m);a.out=4;b.out=4;b.grade={temp:1500,exposure:-.3,saturation:.8};b.transition={id:'CircleFeather',seconds:1};project.clips=[a,b];project.name='My first edit';selected=b.id;head=3.5;changed();}$('#loading').hidden=true;renderPanel();updateTimeline();await render();if('serviceWorker'in navigator&&location.protocol!=='file:'&&!window.webkit?.messageHandlers?.lookroomExport)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(e){$('#loading').textContent=`Could not start Lookroom: ${e.message}. Reload to try again.`;console.error(e);}}
boot();
